def norm_id(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = str(s).casefold()
    s = "".join(ch if ch.isalnum() else " " for ch in s)
    return " ".join(s.split())


# ---------------------------------------------------------------- reading

def read_text(path):
    with open(path, "r", encoding="utf-8-sig", newline="") as f:
        return f.read()


def parse_csv(path):
    text = read_text(path)
    lines = text.splitlines(True)
    meta = {}
    i = 0
    while i < len(lines):
        raw = lines[i].strip()
        if raw == "":
            i += 1
            continue
        if raw.startswith("#"):
            body = raw[1:]
            if ":" in body:
                k, v = body.split(":", 1)
                meta[k.strip().lower()] = v.strip()
            i += 1
            continue
        break
    rest = "".join(lines[i:])
    reader = csv.reader(io.StringIO(rest, newline=""))
    header = None
    records = []
    for row in reader:
        if not row or all(c.strip() == "" for c in row):
            continue
        if header is None:
            header = [h.strip().lower() for h in row]
            continue
        d = {}
        for name, val in zip(header, row):
            if name not in d:
                d[name] = val
        ranks = {}
        for name, val in d.items():
            m = re.fullmatch(r"rank(\d+)", name)
            if not m:
                continue
            marks = []
            for part in val.split("|"):
                p = part.strip()
                if not p:
                    continue
                if p[:3].lower() == "wi:":
                    marks.append(("w", p[3:]))
                else:
                    marks.append(("c", p))
            if marks:
                ranks[int(m.group(1))] = marks
        records.append((d.get("ballot", ""), d.get("contest", "").strip()
                        if False else d.get("contest", ""), ranks))
    return meta, records


def parse_jsonl(path):
    text = read_text(path)
    meta = None
    records = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        if meta is None:
            meta = {k: obj[k] for k in obj}
            continue
        ranks = {}
        for m in obj.get("marks", []):
            r = int(m["rank"])
            if "candidate" in m and m["candidate"] is not None:
                ranks.setdefault(r, []).append(("c", str(m["candidate"]).strip()))
            if "write_in" in m and m["write_in"] is not None:
                ranks.setdefault(r, []).append(("w", str(m["write_in"])))
        records.append((obj.get("ballot", ""), obj.get("contest", ""), ranks))
    return meta or {}, records


def load_batches(indir):
    cvr = os.path.join(indir, "cvr")
    best = {}
    names = sorted(os.listdir(cvr)) if os.path.isdir(cvr) else []
    for name in names:
        path = os.path.join(cvr, name)
        if not os.path.isfile(path):
            continue
        if name.endswith(".csv"):
            meta, recs = parse_csv(path)
        elif name.endswith(".jsonl"):
            meta, recs = parse_jsonl(path)
        else:
            continue
        batch = str(meta.get("batch", ""))
        rev = int(str(meta.get("revision", "0")).strip())
        status = str(meta.get("status", "final")).strip().lower()
        cur = best.get(batch)
        if cur is None or rev > cur[0]:
            best[batch] = (rev, status, recs)
    out = []
    for batch in sorted(best):
        rev, status, recs = best[batch]
        if status == "void":
            continue
        out.extend(recs)
    return out


# ---------------------------------------------------------------- counting

SKIP, PASS, CHOICE, OVER = "S", "P", "C", "O"


def read_ballot(ranks, max_ranks, withdrawn, wi_map, known):
    """Return list of rankings: (kind, candidate-key or None)."""
    seen = set()
    out = []
    for r in range(1, max_ranks + 1):
        cands = set()
        for kind, val in ranks.get(r, ()):
            if kind == "w":
                k = wi_map.get(norm_text(val))
                if k is not None:
                    cands.add(k)
            else:
                cands.add(norm_id(val))
        if not cands:
            out.append((SKIP, None))
            continue
        cands = {c for c in cands if c not in withdrawn}
        if not cands:
            out.append((PASS, None))
            continue
        before = cands
        cands = {c for c in before if c not in seen}
        seen |= before
        if not cands:
            out.append((SKIP, None))
        elif len(cands) == 1:
            out.append((CHOICE, next(iter(cands))))
        else:
            out.append((OVER, None))
    return out


def count_for(rk, continuing):
    n = len(rk)
    for i, (kind, c) in enumerate(rk):
        if kind == CHOICE:
            if c in continuing:
                return c
        elif kind == PASS:
            continue
        elif kind == OVER:
            return None
        else:  # SKIP
            if i + 1 < n and rk[i + 1][0] == SKIP:
                return None
    return None


def tally_contest(contest, records):
    cid = contest["id"]
    max_ranks = int(contest.get("max_ranks", 0))
    display = {}
    withdrawn = set()
    continuing = []
    for c in contest.get("candidates", []):
        k = norm_id(c["id"])
        display[k] = c["id"]
        if c.get("status", "active") == "withdrawn":
            withdrawn.add(k)
        else:
            continuing.append(k)
    wi_map = {}
    for w in contest.get("write_ins", []):
        k = norm_id(w["id"])
        display[k] = w["id"]
        continuing.append(k)
        for t in [w.get("name", "")] + list(w.get("aliases", [])):
