        lot.setdefault(norm_id(x), i)

    ballots = [read_ballot(r, max_ranks, withdrawn, wi_map, display)
               for r in records]
    total = len(ballots)
    cont = list(dict.fromkeys(continuing))
    cont_set = set(cont)
    history = []  # list of dict candidate -> votes
    rounds = []
    winner = None
    while True:
        votes = {c: 0 for c in cont}
        active = 0
        for rk in ballots:
            c = count_for(rk, cont_set)
            if c is not None:
                votes[c] += 1
                active += 1
        history.append(votes)
        rnd = {"round": len(history),
               "tallies": {display[c]: votes[c] for c in cont},
               "exhausted": total - active,
               "eliminated": []}
        rounds.append(rnd)
        if active == 0:
            break
        win = None
        for c in cont:
