    by_contest = {}
    for ballot, contest, ranks in records:
        by_contest.setdefault(contest, []).append(ranks)
    result = {"election": election.get("election"), "contests": []}
    for c in election.get("contests", []):
        result["contests"].append(tally_contest(c, by_contest.get(c["id"], [])))
    d = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(d, exist_ok=True)
    with open(outfile, "w", encoding="utf-8") as f:
